using System;using System.Linq;using System.Collections.Generic;
namespace GearLab {
 public sealed class MechanismShaftState {public string Id;public double SpeedRatio,Rpm,PathEfficiency=1,AvailableTorque,RequiredTorque,LoadPower,RequiredPower;public string Parent;public MechanismLink ParentLink;public bool Connected;}
 public sealed class MechanismMeshState {public string LinkId,DriverId,DrivenId;public double Ratio,Efficiency,Torque,TangentialForce,RadialForce,AxialForce,CapacityForce;}
 public sealed class MechanismSolution {public Dictionary<string,MechanismShaftState> Shafts=new Dictionary<string,MechanismShaftState>();public List<MechanismMeshState> Meshes=new List<MechanismMeshState>();public List<string> Errors=new List<string>(),Notes=new List<string>();public double InputPower,RequiredTorque,RequiredPower;public bool Overloaded;public bool Valid{get{return Errors.Count==0;}}}
 public static class MechanismSolver {
  sealed class Edge {public string A,B;public double Speed,Efficiency;public MechanismLink Link;}
  public static MechanismSolution Solve(MechanismProject p){var r=new MechanismSolution();if(!MechanismCad.Finite(p.InputRpm)||!MechanismCad.Finite(p.InputTorque)||Math.Abs(p.InputRpm)>60000||p.InputTorque<0||p.InputTorque>1000000){r.Errors.Add("Недопустимый входной момент или обороты.");return r;}foreach(var s in p.Parts.Where(a=>a.Kind=="shaft"))r.Shafts[s.Id]=new MechanismShaftState{Id=s.Id};r.InputPower=Math.Abs(p.InputRpm)*Math.PI/30*p.InputTorque;if(r.Shafts.Count==0){r.Notes.Add("Добавьте вал и назначьте его входом.");return r;}if(!r.Shafts.ContainsKey(p.DriveShaftId??"")){r.Errors.Add("Выберите входной вал.");return r;}var edges=new List<Edge>();var linkIds=new HashSet<string>();foreach(var l in p.Links){if(string.IsNullOrWhiteSpace(l.Id)||!linkIds.Add(l.Id)){r.Errors.Add("Идентификаторы связей повторяются.");continue;}var a=p.Find(l.FromId);var b=p.Find(l.ToId);var sa=p.Shaft(a);var sb=p.Shaft(b);if(a==null||b==null||sa==null||sb==null||sa.Id==sb.Id){r.Errors.Add("Связь требует двух деталей на разных валах.");continue;}if(!MechanismCad.Finite(l.Efficiency)||l.Efficiency<=0||l.Efficiency>1||!MechanismCad.Finite(l.PlacementAngle)){r.Errors.Add("КПД связи должен быть больше 0 и не выше 1.");continue;}double speed=1;var x=p.Position(a);var y=p.Position(b);double distance=Math.Sqrt(Math.Pow(x[0]-y[0],2)+Math.Pow(x[1]-y[1],2));if(l.Kind=="gear"){if(a.Kind!="gear"||b.Kind!="gear"||Math.Abs(a.Module-b.Module)>1e-9){r.Errors.Add("Для зацепления нужны две шестерни с одинаковым модулем.");continue;}if(Math.Abs(a.PressureAngle-b.PressureAngle)>.001){r.Errors.Add("Углы зацепления шестерён должны совпадать.");continue;}if(Math.Abs(a.HelixAngle+b.HelixAngle)>.001||(a.GearForm=="herringbone")!=(b.GearForm=="herringbone")){r.Errors.Add("Для параллельных валов выберите ответные шестерни: одинаковый тип и противоположные углы наклона зубьев.");continue;}double target=(a.PitchDiameter+b.PitchDiameter)/2;if(Math.Abs(distance-target)>.02)r.Errors.Add(a.Name+" ↔ "+b.Name+": межосевое должно быть "+Engine.F(target)+" мм; нажмите «Расставить связи».");if(Math.Min(x[2]+a.Length,y[2]+b.Length)-Math.Max(x[2],y[2])<.1)r.Errors.Add(a.Name+" ↔ "+b.Name+": зубчатые венцы не перекрываются по Z.");speed=-(double)a.Teeth/b.Teeth;}else if(l.Kind=="belt"){if(a.Kind!="pulley"||b.Kind!="pulley"){r.Errors.Add("Для ремня нужны два шкива.");continue;}if(distance<=(a.Diameter+b.Diameter)/2+.1)r.Errors.Add("Шкивы пересекаются: увеличьте межосевое расстояние.");if(Math.Min(x[2]+a.Length,y[2]+b.Length)-Math.Max(x[2],y[2])<.1)r.Errors.Add("Шкивы не находятся в одной осевой плоскости.");speed=a.Diameter/b.Diameter;}else if(l.Kind=="coupling"){if(a.Kind!="shaft"||b.Kind!="shaft"||distance>.02)r.Errors.Add("Жёсткая муфта соединяет два соосных вала.");}else{r.Errors.Add("Неизвестный тип связи.");continue;}edges.Add(new Edge{A=sa.Id,B=sb.Id,Speed=speed,Efficiency=l.Efficiency,Link=l});}
   if(r.Errors.Count>0)return r;
   var root=r.Shafts[p.DriveShaftId];root.SpeedRatio=1;root.Connected=true;var order=new List<MechanismShaftState>{root};var seenLinks=new HashSet<string>();for(int i=0;i<order.Count;i++){var current=order[i];foreach(var edge in edges.Where(e=>e.A==current.Id||e.B==current.Id)){if(!seenLinks.Add(edge.Link.Id))continue;string other=edge.A==current.Id?edge.B:edge.A;double factor=edge.A==current.Id?edge.Speed:1/edge.Speed;var next=r.Shafts[other];if(next.Connected){r.Errors.Add("Замкнутый контур / несколько путей передачи момента. Для расчёта усилий используйте разветвлённую цепь без замкнутых петель.");continue;}next.Connected=true;next.Parent=current.Id;next.ParentLink=edge.Link;next.SpeedRatio=current.SpeedRatio*factor;next.PathEfficiency=current.PathEfficiency*edge.Efficiency;if(next.PathEfficiency<1e-12||!MechanismCad.Finite(next.SpeedRatio)||Math.Abs(next.SpeedRatio)<1e-12||Math.Abs(next.SpeedRatio)>1e12){r.Errors.Add("Слишком большое суммарное передаточное число.");continue;}order.Add(next);}}
   if(r.Errors.Count>0)return r;
   foreach(var state in order){var part=p.Find(state.Id);state.Rpm=p.InputRpm*state.SpeedRatio;state.AvailableTorque=p.InputTorque*state.PathEfficiency/Math.Abs(state.SpeedRatio);state.RequiredTorque=part.LoadTorque;state.LoadPower=part.LoadTorque*Math.Abs(state.Rpm)*Math.PI/30;}
   for(int i=order.Count-1;i>=0;i--){var current=order[i];current.RequiredPower=current.RequiredTorque*Math.Abs(current.Rpm)*Math.PI/30;if(current.Parent!=null){var parent=r.Shafts[current.Parent];parent.RequiredTorque+=current.RequiredTorque*Math.Abs(current.SpeedRatio/parent.SpeedRatio)/current.ParentLink.Efficiency;}}
   foreach(var state in order.Where(s=>s.Parent!=null)){var link=state.ParentLink;var parent=r.Shafts[state.Parent];var a=p.Find(link.FromId);var b=p.Find(link.ToId);bool forward=p.Shaft(a).Id==parent.Id;var driver=forward?a:b;var driven=forward?b:a;double torque=state.RequiredTorque*Math.Abs(state.SpeedRatio/parent.SpeedRatio)/link.Efficiency,ft=link.Kind=="coupling"?0:2000*torque/driver.PitchDiameter;r.Meshes.Add(new MechanismMeshState{LinkId=link.Id,DriverId=driver.Id,DrivenId=driven.Id,Ratio=parent.SpeedRatio/state.SpeedRatio,Efficiency=link.Efficiency,Torque=torque,TangentialForce=ft,RadialForce=link.Kind=="gear"?ft*Math.Tan(driver.PressureAngle*Math.PI/180):0,AxialForce=link.Kind=="gear"&&driver.GearForm!="herringbone"?ft*Math.Abs(Math.Tan(driver.HelixAngle*Math.PI/180)):0,CapacityForce=link.Kind=="coupling"?0:2000*parent.AvailableTorque/driver.PitchDiameter});}
   r.RequiredTorque=root.RequiredTorque;r.RequiredPower=root.RequiredPower;r.Overloaded=r.RequiredTorque>p.InputTorque+1e-8;
   foreach(var state in r.Shafts.Values.Where(s=>!s.Connected))r.Notes.Add(p.Find(state.Id).Name+": не связан с входом; обороты и усилия не определены.");foreach(var part in p.Parts.Where(a=>(a.Kind=="gear"||a.Kind=="pulley")&&string.IsNullOrEmpty(a.ShaftId)))r.Notes.Add(part.Name+": свободная деталь; посадите её на вал для передачи вращения.");if(order.Any(s=>order.Count(t=>t.Parent==s.Id)>1))r.Notes.Add("Предельный момент в таблице относится к одной ветви при использовании всего входного момента. Одновременно такой момент на всех выходах получить нельзя; заданные нагрузки суммируются отдельно.");r.Notes.Add("Установившийся режим, параллельные оси Z. КПД задаётся пользователем; расчёт без динамики, деформаций и проверки прочности зубьев. Для ремня предполагается отсутствие проскальзывания; Ft — разность натяжений, не полная нагрузка на опоры.");if(r.Overloaded)r.Notes.Add("Заданные обороты при этих нагрузках не обеспечены: нужен больший входной момент или меньшая нагрузка. Динамика остановки не моделируется.");return r;
  }
 }
}
